#[path = "solution.rs"]
mod solution;

use solution::heaviest_route;

#[test]
fn handles_single_node_and_selects_the_heaviest_leaf_path() {
    assert_eq!(heaviest_route(1, 0, &[]), Some(0));

    let edges = [(0, 1, 5), (0, 2, 2), (1, 3, 4), (1, 4, -10)];
    assert_eq!(heaviest_route(5, 0, &edges), Some(9));
    assert_eq!(edges, [(0, 1, 5), (0, 2, 2), (1, 3, 4), (1, 4, -10)]);
}

#[test]
fn preserves_negative_route_sums() {
    let edges = [(0, 1, -5), (0, 2, -2)];
    assert_eq!(heaviest_route(3, 0, &edges), Some(-2));
}

#[test]
fn accepts_a_nonzero_root() {
    let edges = [(2, 0, 7), (2, 1, 4), (0, 3, 1)];
    assert_eq!(heaviest_route(4, 2, &edges), Some(8));
}

#[test]
fn rejects_invalid_counts_indices_and_self_edges() {
    assert_eq!(heaviest_route(0, 0, &[]), None);
    assert_eq!(heaviest_route(2, 2, &[(0, 1, 1)]), None);
    assert_eq!(heaviest_route(3, 0, &[(0, 1, 1)]), None);
    assert_eq!(heaviest_route(2, 0, &[(0, 2, 1)]), None);
    assert_eq!(heaviest_route(2, 0, &[(1, 1, 1)]), None);
}

#[test]
fn rejects_parent_violations_cycles_and_unreachable_nodes() {
    assert_eq!(heaviest_route(2, 0, &[(1, 0, 3)]), None);
    assert_eq!(heaviest_route(3, 0, &[(0, 1, 1), (2, 1, 2)]), None);
    assert_eq!(heaviest_route(3, 0, &[(1, 2, 1), (2, 1, 1)]), None);
}

#[test]
fn rejects_positive_and_negative_path_overflow() {
    assert_eq!(heaviest_route(3, 0, &[(0, 1, i64::MAX), (1, 2, 1)]), None);
    assert_eq!(heaviest_route(3, 0, &[(0, 1, i64::MIN), (1, 2, -1)]), None);
}

